// 全部geminiが生成したテスト all test cases were fully generated by Gemini 4 Argon

package net.shotakosaka.wormquant

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

class FilenameParserTest {

    @Test
    fun testParseStandardFilenameWithRawValuesAndConstants() {
        val parser = FilenameParser(
            useRegex = false,
            delimiter = "_",
            mappings = listOf(
                ParameterMapping("Genotype", "1-3"),
                ParameterMapping("Auxin", "4"),
                ParameterMapping("RNAi", "5"),
                ParameterMapping("Date", "6"),
                ParameterMapping("Group", "7"),
                ParameterMapping("Exposure", "8"),
                ParameterMapping("Species", "C. elegans"),
                ParameterMapping("Mag", "20x")
            )
        )

        val filename = "Teft-3_H_Rdeg_noaux_cco-1_210826001_G1_2.5_ch00.tif"
        val result = parser.parse(filename)

        assertNotNull(result)
        assertEquals("Teft-3_H_Rdeg", result["Genotype"])
        assertEquals("noaux", result["Auxin"])
        assertEquals("cco-1", result["RNAi"])
        assertEquals("210826001", result["Date"])
        assertEquals("G1", result["Group"])
        assertEquals("2.5", result["Exposure"])
        assertEquals("C. elegans", result["Species"])
        assertEquals("20x", result["Mag"])
    }

    @Test
    fun testParseWithRegexMode() {
        val parser = FilenameParser(
            useRegex = true,
            regexPattern = FilenameParser.DEFAULT_REGEX
        )

        val filename = "Teft-3_H_Rdeg_noaux_cco-1_210826001_G1_2.5_ch00.tif"
        val result = parser.parse(filename)

        assertNotNull(result)
        assertEquals("Teft-3_H_Rdeg", result["genotype"])
        assertEquals("noaux", result["auxin"])
        assertEquals("cco-1", result["rnai"])
        assertEquals("210826", result["date"])
        assertEquals("G1", result["group"])
        assertEquals("2.5", result["exposure"])
    }

    @Test
    fun testCustomParametersAndDelimiter() {
        val customParser = FilenameParser(
            useRegex = false,
            delimiter = "-",
            mappings = listOf(
                ParameterMapping("Strain", "1"),
                ParameterMapping("Condition", "2"),
                ParameterMapping("Dose", "3")
            )
        )

        val filename = "N2-heatshock-100uM.tif"
        val result = customParser.parse(filename)

        assertNotNull(result)
        assertEquals("N2", result["Strain"])
        assertEquals("heatshock", result["Condition"])
        assertEquals("100uM", result["Dose"])
    }

    @Test
    fun testInsufficientTokensReturnsNull() {
        val parser = FilenameParser(
            useRegex = false,
            delimiter = "_",
            mappings = listOf(ParameterMapping("Param1", "10"))
        )
        val filename = "short_filename.tif"
        val result = parser.parse(filename)
        assertNull(result)
    }
}
